#include <stdio.h>

int main(void) {
    int a[4] = {50, 60, 90, 100};
    int sum = 0, max = a[0], passed = 0;
    for (int i = 0; i < 4; i++) {
        sum += a[i];
        if (a[i] > max) { max = a[i]; }
        if (a[i] >= 60) { passed++; }
    }
    printf("%.2f %d %d\n", (double)sum / 4, max, passed);
    return 0;
}

