#include <stdio.h>

int main(void) {
    int n, a[50], count = 0;
    if (scanf("%d", &n) != 1) { return 1; }
    for (int i = 0; i < n; i++) { if (scanf("%d", &a[i]) != 1) { return 1; } }
    for (int i = 1; i < n - 1; i++) {
        if (a[i] > a[i - 1] && a[i] > a[i + 1]) { count++; }
    }
    printf("%d\n", count);
    return 0;
}

